	/// <summary>
    /// PaffH 12.05.21
    /// check prefix in itemId
    /// </summary>
    protected void initItemId()
    {
        if (!itemId)  //AVA/WEN/2025/01/21  AVA_012939_CreateNewCompanyProduct
        {
            itemId = NDXItemIdHandler::constructFromDataAreaId(curExt()).checkItemId(ecoResProduct.productNumber(), "@NDX:NDXCheckItemIdAttachedMessage1");
        }
        next initItemId();
    }
